return processedItems.map(item => ({ json: item }));

const items = $input.all();

function wrapToLines(text, wordsPerLine = 5) {
  const words = (text || '').split(/\s+/);
  const lines = [];
  for (let i = 0; i < words.length; i += wordsPerLine) {
    lines.push(words.slice(i, i + wordsPerLine).join(' '));
  }
  return lines;
}

function chunkLines(lines, chunkSize = 4) {
  const chunks = [];
  for (let i = 0; i < lines.length; i += chunkSize) {
    chunks.push(lines.slice(i, i + chunkSize));
  }
  return chunks;
}

return items.map(item => {
  const data = item.json;

  // Dynamic wrapping based on text length
  const urduWords = (data.urdu_text || '').split(/\s+/).length;
  const englishWords = (data.english_text || '').split(/\s+/).length;

  // Adjust words per line based on total word count
  const urduWordsPerLine = urduWords > 40 ? 10 : urduWords > 25 ? 10 : 9;
  const englishWordsPerLine = englishWords > 50 ? 8 : englishWords > 30 ? 8 : 8;

  // Get lines
  const urduLines = wrapToLines(data.urdu_text, urduWordsPerLine);
  const englishLines = wrapToLines(data.english_text, englishWordsPerLine);

  // Create chunks of 4 lines each
  const urduChunks = chunkLines(urduLines, 4);
  const englishChunks = chunkLines(englishLines, 4);

  return {
    json: {
      ...data,
      urdu_lines: urduLines, // Keep original for reference
      english_lines: englishLines, // Keep original for reference
      urdu_chunks: urduChunks, // New chunked data
      english_chunks: englishChunks, // New chunked data
      total_urdu_chunks: urduChunks.length,
      total_english_chunks: englishChunks.length
    }
  };
});

// Generate ayah processing list with all required data
const inputParams = $('Video Parameters').first().json;
const surahData = $input.first().json;

const surahNumber = inputParams.surah_number;
const fromAyah = inputParams.from_ayah;
const toAyah = inputParams.to_ayah;
const reciter = inputParams.reciter;
const translationAudio = inputParams.translation_audio;

// Create processing list for each ayah
const ayahsToProcess = [];
for (let ayahNum = fromAyah; ayahNum <= toAyah; ayahNum++) {
  const formattedAyahNumber = String(surahNumber).padStart(3, '0') + String(ayahNum).padStart(3, '0');

  ayahsToProcess.push({
    // Basic ayah info
    ayah_number: ayahNum,
    formatted_ayah_number: formattedAyahNumber,
    surah_number: surahNumber,

    // Audio info
    reciter: reciter,
    translation_audio: translationAudio,

    // Text content (from surah data)
    arabic_text: surahData.arabic1 && surahData.arabic1[ayahNum - 1] ? surahData.arabic1[ayahNum - 1] : '',
    urdu_text: surahData.urdu && surahData.urdu[ayahNum - 1] ? surahData.urdu[ayahNum - 1] : '',
    english_text: surahData.english && surahData.english[ayahNum - 1] ? surahData.english[ayahNum - 1] : '',

    // Surah info for display
    surah_name_arabic: surahData.surahNameArabicLong,
    surah_name_english: surahData.surahName,
    surah_range: `${fromAyah}-${toAyah}`,

    // Video parameters
    background_images_path: inputParams.background_images_path,
    fonts_path: inputParams.fonts_path,
    temp_path: inputParams.temp_path,
    output_path: inputParams.output_path,
    arabic_font: inputParams.arabic_font,
    urdu_font: inputParams.urdu_font,
    english_font: inputParams.english_font
  });
}

return ayahsToProcess.map(item => ({ json: item }));

// This would combine multiple ayahs into one sequential video
const items = $input.all();
let currentTime = 0;
const combinedSegments = [];

for (const item of items) {
  const data = item.json;
  // Calculate timing for this ayah segment
  const segmentDuration = data.reciter_duration + data.translation_duration + 4; // +4 for transitions

  combinedSegments.push({
    ...data,
    segment_start: currentTime,
    segment_end: currentTime + segmentDuration
  });

  currentTime += segmentDuration;
}

return combinedSegments.map(item => ({ json: item }));

// ---------- Path Sanitizer ----------
function fixPath(path) {
  if (!path) return '';
  return path
    .replace(/\n/g, '')        // remove accidental newline chars
    .replace(/\r/g, '')        // remove carriage return
    .trim();                   // remove spaces at start/end
}

// ---------- Text Escaper ----------
function escapeTextForFFmpeg(text) {
  if (!text) return '';
  let escaped = text.replace(/\\/g, '\\\\'); // backslashes
  escaped = escaped.replace(/%/g, '\\%');    // percent signs
  escaped = escaped.replace(/:/g, '\\:');    // colons
  escaped = escaped.replace(/'/g, "\\\\\\'");// single quotes
  return escaped;
}

const items = $input.all();
const first = items[0].json;

// Sanitize paths
const background_videos_path = fixPath(first.background_videos_path);
const fonts_path = fixPath(first.fonts_path);
const english_font = fixPath(first.english_font);
const output_path = fixPath(first.output_path);
const surah_png_path = fixPath(first.surah_png_path);

// Defaults for Surah info
const surah_range_val = first.surah_range && first.surah_range.trim() !== '' ? first.surah_range : '1-1';
const surah_Name_val  = first.surah_Name && first.surah_Name.trim() !== '' ? first.surah_Name : `Surah_${first.surah_number || 'Unknown'}`;

// Escaped values
const escapedRange = escapeTextForFFmpeg(surah_range_val);
const escapedName  = escapeTextForFFmpeg(surah_Name_val);

// Debug Logs
console.log('✅ Surah Range:', surah_range_val);
console.log('✅ Surah Name:', surah_Name_val);
console.log('✅ Fonts Path:', fonts_path);
console.log('✅ English Font File:', english_font);

// Resolution
const width = 1080;
const height = 1920;

// Total duration calc
let totalDuration = 1;
items.forEach(item => {
  const reciterDur = parseFloat(item.json.reciter_duration) || 0;
  const translationDur = parseFloat(item.json.translation_duration) || 0;
  totalDuration += reciterDur + 1 + translationDur + 1.5;
});

// Select clips
function selectClips(path, totalDuration) {
  const available = Array.from({ length: 44 }, (_, i) => `${i + 1}.mp4`);
  const clipDuration = 6;
  const clipsNeeded = Math.ceil(totalDuration / clipDuration);
  const selected = [];
  for (let i = 0; i < clipsNeeded; i++) {
    const randomIndex = Math.floor(Math.random() * available.length);
    selected.push({
      file: fixPath(`${path}/${available[randomIndex]}`),
      start: Math.floor(Math.random() * 2),
      duration: clipDuration
    });
  }
  return selected;
}

const selectedClips = selectClips(background_videos_path, totalDuration);

let inputArgs = [], videoFilters = [], audioDelays = [], audioInputs = [];

// Video inputs
selectedClips.forEach((clip) => {
  inputArgs.push(`-ss ${clip.start} -t ${clip.duration} -i "${clip.file}"`);
});

// Bismillah PNG
inputArgs.push(`-i "${fixPath(surah_png_path).replace(/[^\\/]*\.png$/, 'bismillah.png')}"`);
const bismillahInputIndex = selectedClips.length;

// Surah PNG
inputArgs.push(`-i "${fixPath(surah_png_path)}"`);
const surahInputIndex = selectedClips.length + 1;

// Prepare clips
const prepared = selectedClips.map((_, i) =>
  `[${i}:v]scale=${width}:${height}:force_original_aspect_ratio=increase,crop=${width}:${height},setsar=1[clip_${i}]`
);
const concatInputs = selectedClips.map((_, i) => `[clip_${i}]`).join('');
videoFilters.push(`${prepared.join(';')};${concatInputs}concat=n=${selectedClips.length}:v=1:a=0[bg_original]`);

const englishFontPath = `${fonts_path}/${english_font}`.replace(/\\/g, '\\\\');

// Overlays + text
videoFilters.push(
  `[${bismillahInputIndex}:v]scale=576:288[scaled_bismillah]`,
  `[bg_original][scaled_bismillah]overlay=(main_w-overlay_w)/2:80[with_bismillah]`,
  `[${surahInputIndex}:v]scale=520:520[scaled_surah_png]`,
  `[with_bismillah][scaled_surah_png]overlay=(main_w-overlay_w)/2:400[with_surah_png]`,
  `[with_surah_png]drawtext=fontfile='${englishFontPath}':text='Ayah (${escapedRange})':fontsize=45:fontcolor=white@1.0:x=(w-text_w)/2:y=870[with_range]`,
  `[with_range]drawtext=fontfile='${englishFontPath}':text='${escapedName}':fontsize=40:fontcolor=white@1.0:x=(w-text_w)/2:y=930[video_final]`
);

// Audio
let currentTime = 1;
let audioInputIndex = selectedClips.length + 2;

items.forEach((item, index) => {
  const reciter_audio_path = fixPath(item.json.reciter_audio_path);
  const translation_audio_path = fixPath(item.json.translation_audio_path);
  const reciterDur = parseFloat(item.json.reciter_duration) || 0;
  const translationDur = parseFloat(item.json.translation_duration) || 0;

  inputArgs.push(`-i "${reciter_audio_path}"`);
  const reciterInputIndex = audioInputIndex++;
  inputArgs.push(`-i "${translation_audio_path}"`);
  const translationInputIndex = audioInputIndex++;

  const reciterDelay = Math.round(currentTime * 1000);
  audioDelays.push(`[${reciterInputIndex}:a]dynaudnorm=f=150:g=15:p=0.95,acompressor=threshold=-18dB:ratio=3:attack=3:release=100:makeup=2dB,volume=0.63,adelay=${reciterDelay}|${reciterDelay}[reciter_${index}]`);

  const translationDelay = Math.round((currentTime + reciterDur + 1) * 1000);
  audioDelays.push(`[${translationInputIndex}:a]dynaudnorm=f=150:g=15:p=0.95,acompressor=threshold=-18dB:ratio=3:attack=3:release=100:makeup=2dB,volume=0.595,adelay=${translationDelay}|${translationDelay}[translation_${index}]`);

  audioInputs.push(`[reciter_${index}]`, `[translation_${index}]`);

  currentTime += reciterDur + 1 + translationDur + 1.5;
});

// Audio mix
const audioMix = `${audioInputs.join('')}amix=inputs=${audioInputs.length}:duration=longest:dropout_transition=3:normalize=1,dynaudnorm=f=200:g=10:p=0.9,acompressor=threshold=-16dB:ratio=2:attack=5:release=150:makeup=1dB,volume=1.1[audio_out]`;

const filterComplex = [...videoFilters, ...audioDelays, audioMix].join(';');

// Output file
const startAyah = first.formatted_ayah_number || '001';
const endAyah = items[items.length - 1].json.formatted_ayah_number || '001';
const surahNameSafe = surah_Name_val.replace(/\s+/g, '_');
const outputFile = `${output_path}/${surahNameSafe}_Reciter_Translation_Ayah_${startAyah}_to_${endAyah}_${Date.now()}.mp4`;

// Final command
const cmd = `ffmpeg -y ${inputArgs.join(' ')} -filter_complex "${filterComplex}" -map "[video_final]" -map "[audio_out]" -c:v libx264 -preset medium -crf 18 -c:a aac -b:a 320k -ac 2 -ar 48000 -pix_fmt yuv420p -t ${currentTime.toFixed(3)} -r 25 -movflags +faststart "${outputFile}"`;

return [{
  json: {
    ffmpeg_command: cmd,
    output_file: outputFile,
    total_duration: currentTime.toFixed(3),
    ayah_count: items.length,
    selected_videos: selectedClips.map(c => c.file),
    surah_png_used: surah_png_path,
    audio_type: 'reciter_then_translation_enhanced'
  }
}];

// Fix output file path for Read File node
const items = $input.all();

return items.map(item => {
  const data = item.json;

  // Get the original output file path
  let outputFile = data.output_file;

  // Convert Windows backslashes to forward slashes
  // From: \n8n-data\quran-videos\output/filename.mp4  
  // To: /n8n-data/quran-videos/output/filename.mp4
  const correctedPath = outputFile.replace(/\\/g, '/');

  return {
    json: {
      ...data,
      original_output_path: outputFile,
      corrected_file_path: correctedPath,
      video_ready: true,
      status: "Video generation completed successfully"
    }
  };
});
